#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // Simple, cache-friendly CPU schedule:
    //  - j (x/column) is innermost and contiguous in memory.
    //  - parallelize over rows i.
    //  - vectorize over j.
    const int vec = 8; // reasonable default for modern x86 (4-wide double, 8-wide float, etc.)

    init_fict
        .compute_root()
        .vectorize(t, vec);

    init_ex
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_ey
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_hz
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // New fields after a single time step.
    //
    // We express the FDTD update as three pure Funcs (no RDom updates):
    //   1. ey1: updated electric field in y-direction
    //   2. ex1: updated electric field in x-direction
    //   3. hz1: updated magnetic field
    //
    // This makes it easier for Halide to aggressively optimize (fuse, vectorize,
    // and parallelize) the stencil computation.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // --- ey update ----------------------------------------------------------
    //
    // Original C code:
    //
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // In Halide (note: buffer index order is (j, i)):
    //
    //   row i == 0: set to fict_param
    //   rows i >= 1: explicit stencil using hz from previous time step
    //
    // We clamp i-1 to 0 when forming the expression to keep all indices
    // in-bounds, even if the unused branch of select() is evaluated.
    Expr i_minus_1 = Halide::max(i - 1, 0);
    Expr ey_update =
        ey_param(j, i) -
        half * (hz_param(j, i) - hz_param(j, i_minus_1));

    ey1(j, i) = select(i == 0, fict_param, ey_update);

    // --- ex update ----------------------------------------------------------
    //
    // Original C code:
    //
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide indices (j,i). Column j == 0 is left unchanged.
    Expr j_minus_1 = Halide::max(j - 1, 0);
    Expr ex_update =
        ex_param(j, i) -
        half * (hz_param(j, i) - hz_param(j_minus_1, i));

    ex1(j, i) = select(j == 0, ex_param(j, i), ex_update);

    // --- hz update ----------------------------------------------------------
    //
    // Original C code:
    //
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Again, remember buffer layout hz(j, i).
    //
    // We must use the *updated* ex and ey (ex1, ey1), not the old values.
    // Boundary points (i == nx-1 or j == ny-1) are left unchanged.
    //
    // To avoid out-of-bounds when forming neighbors (j+1, i+1), we clamp
    // indices into the valid range. The select() expression ensures that
    // boundary points still get the original hz_param(j,i) value, so
    // clamped neighbor accesses at the boundary are computed but ignored.
    Expr j_plus_1 = Halide::min(j + 1, NY - 1);
    Expr i_plus_1 = Halide::min(i + 1, NX - 1);

    Expr ex_center = ex1(j, i);
    Expr ex_right  = ex1(j_plus_1, i);
    Expr ey_center = ey1(j, i);
    Expr ey_down   = ey1(j, i_plus_1);

    Expr curl_e =
        (ex_right - ex_center) +
        (ey_down  - ey_center);

    Expr hz_interior =
        hz_param(j, i) - seven_tenths * curl_e;

    // Only update interior region i < nx-1, j < ny-1. Boundary cells keep
    // their previous value (hz_param).
    hz1(j, i) = select(j < NY - 1 && i < NX - 1,
                       hz_interior,
                       hz_param(j, i));

    // ------------------------
    // Scheduling for the step:
    // ------------------------
    //
    // Goal:
    //  - Good data locality: process tiles of hz1 and compute ex1/ey1 just
    //    for those tiles.
    //  - Vectorize across j (contiguous dimension).
    //  - Parallelize across tiles (rows × columns of tiles).
    //
    // Layout recap:
    //   dim 0 (j) : 0 .. ny-1, contiguous
    //   dim 1 (i) : 0 .. nx-1, stride ny
    //
    const int vec = 8;      // vector width over j
    const int tile_j = 64;  // tile size in j (x / columns)
    const int tile_i = 32;  // tile size in i (y / rows)

    Var jo("jo"), io("io"), ji("ji"), ii("ii"), tile("tile");

    // Tile hz1, fuse the tile coordinates, parallelize over tiles,
    // and vectorize across the inner j loop.
    hz1
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile)
        .parallel(tile)
        .vectorize(ji, vec);

    // Compute ex1 and ey1 per tile of hz1, and vectorize over j.
    // This gives good producer-consumer locality without needing to
    // materialize ex1/ey1 for the entire image prior to hz1.
    ex1
        .compute_at(hz1, tile)
        .vectorize(j, vec);

    ey1
        .compute_at(hz1, tile)
        .vectorize(j, vec);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit();

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j2 = 0; j2 < ny; j2++) {
                std::cerr << ex_final(j2, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j2 = 0; j2 < ny; j2++) {
                std::cerr << ey_final(j2, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j2 = 0; j2 < ny; j2++) {
                std::cerr << hz_final(j2, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
