```c++
#include <algorithm>
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // Simple but reasonably efficient CPU schedule for initialization:
    Target target = get_jit_target_from_environment();
    const int vec = std::max(1, natural_vector_size<num_t>(target));

    Var jo("jo"), ji("ji");

    // Parallelize across rows (i) and vectorize along contiguous j.
    init_ex.compute_root()
        .split(j, jo, ji, vec)
        .parallel(i)
        .vectorize(ji);
    init_ey.compute_root()
        .split(j, jo, ji, vec)
        .parallel(i)
        .vectorize(ji);
    init_hz.compute_root()
        .split(j, jo, ji, vec)
        .parallel(i)
        .vectorize(ji);

    init_fict.compute_root()
        .vectorize(t, vec);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // Derive width (ny) and height (nx) from the input buffers.
    // dim(0): j in [0 .. ny-1], dim(1): i in [0 .. nx-1].
    Expr width  = ex_param.dim(0).extent();
    Expr height = ex_param.dim(1).extent();

    // -------------------------------------------------------------------------
    // Optimized single-timestep update, expressed as pure Funcs.
    //
    // We avoid RDom-based updates and instead express the entire update as
    // pure functions with explicit boundary handling. This allows much
    // easier and more aggressive scheduling (vectorization/parallelization)
    // and improves data locality.
    // -------------------------------------------------------------------------

    // Boundary-safe view of Hz so we can access i-1 or j-1 without going
    // out-of-bounds. Using clamp keeps Halide's bounds inference happy.
    Func hz_bc("hz_bc");
    hz_bc(j, i) = hz_param(
        clamp(j, 0, width  - 1),
        clamp(i, 0, height - 1));

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // ey update:
    //
    // C code:
    //   for (j = 0; j < NY; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   for (i = 1; i < NX; i++)
    //     for (j = 0; j < NY; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // In Halide (exploiting the (j, i) layout):
    //   * i == 0 row is set to fict_param,
    //   * other rows use the stencil in the i-direction.
    ey1(j, i) = select(
        i == 0,
        // First row: directly use fict_param (ey[0][j] = fict[t])
        fict_param,
        // Rows i >= 1:
        ey_param(j, i) -
            half * (hz_bc(j, i) - hz_bc(j, i - 1))
    );

    // ex update:
    //
    // C code:
    //   for (i = 0; i < NX; i++)
    //     for (j = 1; j < NY; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // In Halide:
    //   * j == 0 column keeps its old value,
    //   * other columns use the stencil in the j-direction.
    ex1(j, i) = select(
        j == 0,
        // First column: untouched
        ex_param(j, i),
        // Columns j >= 1:
        ex_param(j, i) -
            half * (hz_bc(j, i) - hz_bc(j - 1, i))
    );

    // Boundary-safe views of ex1 and ey1 for Hz update.
    //
    // Hz's stencil needs ex(i, j+1) and ey(i+1, j). To avoid out-of-bounds
    // even in the boundary regions (where we later select the old Hz value),
    // we explicitly clamp the access to [0 .. width-1] and [0 .. height-1].
    Func ex1_bc("ex1_bc"), ey1_bc("ey1_bc");
    ex1_bc(j, i) = ex1(
        clamp(j, 0, width  - 1),
        clamp(i, 0, height - 1));
    ey1_bc(j, i) = ey1(
        clamp(j, 0, width  - 1),
        clamp(i, 0, height - 1));

    // hz update:
    //
    // C code:
    //   for (i = 0; i < NX - 1; i++)
    //     for (j = 0; j < NY - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Edges i == NX-1 or j == NY-1 keep their previous value of hz.
    //
    // In Halide, with (j, i) layout:
    //   interior:  j < width-1, i < height-1
    //     hz1(j, i) = hz(j, i) - 0.7 * (ex1(j+1, i) - ex1(j, i)
    //                                    + ey1(j, i+1) - ey1(j, i));
    //   border:    otherwise, hz1(j, i) = hz(j, i).
    Expr interior = (j < width - 1) && (i < height - 1);
    Expr hz_center = hz_param(j, i);
    Expr hz_update =
        hz_center -
        seven_tenths *
            ((ex1_bc(j + 1, i) - ex1_bc(j, i)) +
             (ey1_bc(j, i + 1) - ey1_bc(j, i)));
    hz1(j, i) = select(interior, hz_update, hz_center);

    // -------------------------------------------------------------------------
    // Scheduling
    // -------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec = std::max(1, natural_vector_size<num_t>(target));

    Var jo("jo"), ji("ji");

    // All three fields are large 2D arrays. For each we:
    //   * compute at the root,
    //   * parallelize across rows (i),
    //   * vectorize along contiguous j using the target's natural vector width.
    //
    // This exploits spatial locality (j is unit-stride) and multi-core parallelism.
    ex1.compute_root()
        .split(j, jo, ji, vec)
        .parallel(i)
        .vectorize(ji);

    ey1.compute_root()
        .split(j, jo, ji, vec)
        .parallel(i)
        .vectorize(ji);

    hz1.compute_root()
        .split(j, jo, ji, vec)
        .parallel(i)
        .vectorize(ji);

    // hz_bc, ex1_bc, ey1_bc are left inlined into the consumers; they consist
    // only of clamps and direct loads and will be simplified aggressively.

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once with the chosen target; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << ex_final(jj, ii) << '\n';
            }
        }

        // Print ey
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << ey_final(jj, ii) << '\n';
            }
        }

        // Print hz
        for (int ii = 0; ii < nx; ii++) {
            for (int jj = 0; jj < ny; jj++) {
                std::cerr << hz_final(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
