#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    Type num_type = type_of<num_t>();

    // _fict_[t] = (DATA_TYPE) t;
    init_fict(t) = cast(num_type, t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast(num_type, i * (j + 1)) / Expr(nx);
    init_ey(j, i) = cast(num_type, i * (j + 2)) / Expr(ny);
    init_hz(j, i) = cast(num_type, i * (j + 3)) / Expr(nx);

    // Simple but effective schedule: vectorize in the fast (j) dimension,
    // and parallelize over the slow (i) dimension.
    Target target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size(target, num_type);

    // Fictitious array: 1D, just vectorize.
    init_fict.compute_root()
             .vectorize(t, vec_width);

    // 2D fields: row-major in (j,i), so j is contiguous in memory.
    init_ex.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    init_ey.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    init_hz.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Numeric constants, in the correct Halide type.
    Type num_type = type_of<num_t>();
    Expr half         = cast(num_type, 0.5);
    Expr seven_tenths = cast(num_type, 0.7);

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // ------------------------------------------------------------------
    // Pure (non-reduction) definitions corresponding to the original C
    // loops. We express the whole update in a single expression per Func,
    // using min/max to avoid out-of-bounds accesses, instead of using
    // RDom-based update definitions. This makes the pipeline easier for
    // Halide to vectorize and parallelize.
    //
    // Original C (for a fixed t):
    //
    //   for (j = 0; j < NY; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   for (i = 1; i < NX; i++)
    //     for (j = 0; j < NY; j++)
    //       ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    //   for (i = 0; i < NX; i++)
    //     for (j = 1; j < NY; j++)
    //       ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    //   for (i = 0; i < NX-1; i++)
    //     for (j = 0; j < NY-1; j++)
    //       hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
    //                         + ey[i+1][j] - ey[i][j]);
    //
    // Remember: Halide indexing ex(j,i) corresponds to C ex[i][j].
    // ------------------------------------------------------------------

    // EY update:
    //
    // Row i == 0 is set to fict_param.
    // Rows i >= 1 get the finite-difference update using *old* hz.
    //
    // We write a single pure definition over the full domain [0..nx-1]x[0..ny-1]:
    //   - For i == 0, value is fict_param.
    //   - For i > 0, ey_old - 0.5 * (hz(i,j) - hz(i-1,j)).
    // To keep indices in-bounds even when evaluated at i == 0, we use
    // max(i-1, 0) for the neighbor access. The select() then chooses the
    // correct value while the unused branch is still safe to evaluate.
    {
        Expr i_minus1 = max(i - 1, 0);
        Expr ey_old   = ey_param(j, i);
        Expr hz_here  = hz_param(j, i);
        Expr hz_prev  = hz_param(j, i_minus1);

        Expr ey_updated = ey_old - half * (hz_here - hz_prev);

        ey1(j, i) = select(i == 0, fict_param, ey_updated);
    }

    // EX update:
    //
    // Columns j >= 1 get the finite-difference update; column j == 0
    // remains unchanged. This can be expressed as a single formula over
    // all j by using max(j-1, 0), which makes the update at j == 0
    // subtract zero:
    //   ex_new(i,0) = ex_old(i,0) - 0.5*(hz(i,0) - hz(i,0)) == ex_old(i,0).
    {
        Expr j_minus1 = max(j - 1, 0);
        Expr ex_old   = ex_param(j, i);
        Expr hz_here  = hz_param(j, i);
        Expr hz_prev  = hz_param(j_minus1, i);

        ex1(j, i) = ex_old - half * (hz_here - hz_prev);
    }

    // HZ update:
    //
    // Interior domain: 0 <= i < NX-1, 0 <= j < NY-1
    //   hz_new(i,j) = hz_old(i,j)
    //                 - 0.7 * (ex_new(i,j+1) - ex_new(i,j)
    //                          + ey_new(i+1,j) - ey_new(i,j))
    //
    // Boundary rows/cols (i == NX-1 or j == NY-1) remain unchanged.
    //
    // We again write a single pure definition over the full domain, and
    // use a select to keep the boundary equal to the old value. Neighbor
    // accesses use min(i+1, NX-1) / min(j+1, NY-1) so that evaluating the
    // "interior" expression is always in-bounds, even at the edges where
    // the select will discard it.
    {
        Expr j_plus1 = min(j + 1, ny - 1);
        Expr i_plus1 = min(i + 1, nx - 1);

        Expr hz_old = hz_param(j, i);
        Expr ex_here   = ex1(j,       i);
        Expr ex_right  = ex1(j_plus1, i);
        Expr ey_here   = ey1(j,       i);
        Expr ey_down   = ey1(j,       i_plus1);

        Expr hz_update = hz_old
                         - seven_tenths *
                               ((ex_right - ex_here) +
                                (ey_down  - ey_here));

        // Only update interior points; boundaries keep hz_old.
        hz1(j, i) = select((i < nx - 1) && (j < ny - 1), hz_update, hz_old);
    }

    // ------------------------------------------------------------------
    // Scheduling for performance
    //
    // We have three outputs (ex1, ey1, hz1). For this CPU-oriented
    // schedule we:
    //   * parallelize over blocks of the slow (i) dimension
    //   * vectorize across the fast (j) dimension
    //   * tile (j,i) to improve cache locality
    // ------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size(target, num_type);

    // Tile sizes are tunable constants; chosen for decent cache behavior
    // on modern x86-64. They can be adjusted for specific machines.
    const int tile_j = 128;  // columns per tile
    const int tile_i = 32;   // rows per tile

    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    // EX: compute at root, tiled & vectorized across j, parallel over tile rows.
    ex1.compute_root()
       .bound(j, 0, ny)
       .bound(i, 0, nx)
       .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
       .vectorize(ji, vec_width)
       .parallel(io);

    // EY: same schedule as EX for good locality and load balancing.
    ey1.compute_root()
       .bound(j, 0, ny)
       .bound(i, 0, nx)
       .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
       .vectorize(ji, vec_width)
       .parallel(io);

    // HZ: similar schedule. It depends on ex1 and ey1, so Halide will
    // evaluate ex1 & ey1 first, then hz1.
    hz1.compute_root()
       .bound(j, 0, ny)
       .bound(i, 0, nx)
       .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
       .vectorize(ji, vec_width)
       .parallel(io);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j0 = 0; j0 < ny; j0++) {
                std::cerr << ex_final(j0, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j0 = 0; j0 < ny; j0++) {
                std::cerr << ey_final(j0, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j0 = 0; j0 < ny; j0++) {
                std::cerr << hz_final(j0, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
