#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // Precompute reciprocals as Expr to avoid repeated divisions.
    Expr nx_f = cast<num_t>(Expr(nx));
    Expr ny_f = cast<num_t>(Expr(ny));
    Expr inv_nx = cast<num_t>(Expr(1.0)) / nx_f;
    Expr inv_ny = cast<num_t>(Expr(1.0)) / ny_f;

    // _fict_[t] = (DATA_TYPE) t;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    Expr i_f = cast<num_t>(i);
    init_ex(j, i) = i_f * cast<num_t>(j + 1) * inv_nx;
    init_ey(j, i) = i_f * cast<num_t>(j + 2) * inv_ny;
    init_hz(j, i) = i_f * cast<num_t>(j + 3) * inv_nx;

    // Simple but effective schedule: parallelize over rows and vectorize across columns.
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    init_fict.compute_root()
             .vectorize(t, vec_width);

    init_ex.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    init_ey.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    init_hz.compute_root()
           .parallel(i)
           .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // Convenience: extents of the current fields (runtime known via ImageParam).
    Expr ny_extent = ex_param.dim(0).extent();  // number of columns (j)
    Expr nx_extent = ex_param.dim(1).extent();  // number of rows    (i)

    // Old fields as Funcs (just wrappers around the ImageParams) to keep expressions readable.
    Func ex_old("ex_old"), ey_old("ey_old"), hz_old("hz_old");
    ex_old(j, i) = ex_param(j, i);
    ey_old(j, i) = ey_param(j, i);
    hz_old(j, i) = hz_param(j, i);

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // -------------------------------------------------------------------------
    // Pure definitions that exactly match the original C update formulas.
    //
    // We avoid RDom-based updates and instead express each time-step as a
    // single pure expression per point, guarded with selects at boundaries.
    // This makes the pipeline easier for Halide to optimize (vectorize,
    // parallelize, and tile) while preserving the original semantics.
    // -------------------------------------------------------------------------

    // ey new:
    //
    // Original C:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide indices: ey(j, i) == ey[i][j].
    //
    // We combine into a single point-wise definition:
    //   if i == 0:
    //       ey1(j,i) = fict[t]
    //   else:
    //       ey1(j,i) = ey_old(j,i) - 0.5 * (hz_old(j,i) - hz_old(j,i-1))
    //
    // The access hz_old(j, i-1) is guarded with clamp() to keep bounds inference
    // happy, even though the i==0 branch does not use it logically.
    Expr i_minus_1 = clamp(i - 1, 0, nx_extent - 1);
    ey1(j, i) = select(
        i == 0,
        fict_param,
        ey_old(j, i) -
            half * (hz_old(j, i) - hz_old(j, i_minus_1))
    );

    // ex new:
    //
    // Original C:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide indices: ex(j, i) == ex[i][j].
    //
    // Combined point-wise definition:
    //   if j == 0:
    //       ex1(j,i) = ex_old(j,i)
    //   else:
    //       ex1(j,i) = ex_old(j,i) - 0.5 * (hz_old(j,i) - hz_old(j-1,i))
    //
    // Again we clamp j-1 for safe bounds.
    Expr j_minus_1 = clamp(j - 1, 0, ny_extent - 1);
    ex1(j, i) = select(
        j == 0,
        ex_old(j, i),
        ex_old(j, i) -
            half * (hz_old(j, i) - hz_old(j_minus_1, i))
    );

    // hz new:
    //
    // Original C:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
