    //
    // Halide indices: hz(j, i) == hz[i][j].
    //
    // We must use the *updated* ex and ey from this same time-step:
    //   hz1(j,i) = hz_old(j,i) - 0.7 * ((ex1(j+1,i) - ex1(j,i)) +
