    // for i in [0..nx-2], j in [0..ny-2]; otherwise hz1(j,i) = hz_old(j,i).
    //
    // We clamp j+1 and i+1 to stay in-bounds; this has no effect in the
    // "else" branch but avoids out-of-bounds according to Halide's analysis.
    Expr j_plus_1 = min(j + 1, ny_extent - 1);
    Expr i_plus_1 = min(i + 1, nx_extent - 1);

    Expr is_interior = (i < nx_extent - 1) && (j < ny_extent - 1);

    Expr ex_diff = ex1(j_plus_1, i) - ex1(j, i);
    Expr ey_diff = ey1(j, i_plus_1) - ey1(j, i);

    hz1(j, i) = select(
        is_interior,
        hz_old(j, i) - seven_tenths * (ex_diff + ey_diff),
        hz_old(j, i)
    );

    // -------------------------------------------------------------------------
    // Scheduling
    //
    // We have three pure Funcs (ex1, ey1, hz1) that each produce a full 2D
    // field. We:
    //   - compute all at the root level,
    //   - parallelize across rows (i),
    //   - vectorize across columns (j).
    //
    // This yields good data locality (row-major traversal), uses all CPU cores,
    // and exploits SIMD for the inner dimension.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    ex1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    ey1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    hz1.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

